const D = { energy:.55, scale:1, density:.55, speed:1, n:3, hue:32, x:.62, y:.86, style:'steel', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

const sty = P.style;
const bp = (sty==='blueprint'), paper = (sty==='engraving'), sil = (sty==='silhouette'), th = (sty==='thermal');
const H = ((P.hue%360)+360)%360;
const AL = cl(P.alpha,0,100)/100;
const NP = Math.max(1, Math.round(cl(P.n,1,5)));
const HT = u*.48*cl(P.scale,.3,2.0);          // near pylon height
const GG = .55;                                // perspective spacing constant

// ---- slow truck down the line; pylon identity keyed on ABSOLUTE index ------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.d = (S.d||0) + dt * P.speed * (.045 + .05*K.intensity) * (.6 + .5*P.energy);
const pbase = Math.floor(S.d);

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const lowm = (S.l = (S.l||0)*.85 + (A.lowmid||0)*.15);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.3;
// wind: three incommensurate rates -> the span never returns to the same shape
const WA = HT*.022*(.35 + .95*P.energy) * (1 + lowm*.9);
const wind = (ph) => WA*(.60*Math.sin(K.t*.63 + ph) + .28*Math.sin(K.t*1.37 + ph*1.7 + 1.1) + .16*Math.sin(K.t*2.11 + ph*.6));

const BX = cl(P.x,.05,.95)*width, BY = cl(P.y,.4,1.05)*height;
const vx = BX - u*.55, vy = BY - u*.42;      // vanishing point of the line

function ink(a, w, near){
  const al = cl(a*AL, 0, 100);
  if (bp)       stroke(196, 26, 100, al);
  else if (paper) stroke(28, 26, 14, al);
  else if (sil) stroke(H, 24, 5 + 8*(1-near), al);
  else if (th)  stroke(cl(H + 200*(1-near), 0, 360), 70, cl(28 + 54*near, 8, 96), al);
  else          stroke(H, cl(8 + 6*(1-near), 0, 30), cl(24 + 52*near*(.5+.6*glow), 6, 92), al);
  strokeWeight(Math.max(.7, w));
}

// ---- one pylon -------------------------------------------------------------
// arm tips are returned so the conductors can be strung between towers
function pylon(ai, dj){
  const k = 1 + dj*GG;
  if (k < .30) return null;
  const t = 1/k;                                   // perspective scale
  const cx = vx + (BX - vx)*t, by = vy + (BY - vy)*t;
  const ht = HT*t;
  if (ht < u*.012) return null;
  const near = cl((t - .18)/.92, 0, 1);
  const fade = cl(.20 + .95*near, 0, 1);
  const lw = Math.max(.7, ht*.0075);
  const jit = .86 + fr(ai*3.3 + 1.1)*.28;          // seeded per-tower variation
  const wOf = q => ht*(q < .55 ? (.185 - (.185-.072)*(q/.55)) : (.072 - (.072-.042)*((q-.55)/.45)));
  const yOf = q => by - ht*q;
  const tips = [];

  // legs + X bracing
  const nb = Math.max(3, Math.round((3 + cl(P.density,0,1)*5) * (.4 + .7*near)));
  ink(84*fade, lw*1.25, near);
  noFill();
  line(cx - wOf(0), yOf(0), cx - wOf(.55), yOf(.55)); line(cx - wOf(.55), yOf(.55), cx - wOf(1), yOf(1));
  line(cx + wOf(0), yOf(0), cx + wOf(.55), yOf(.55)); line(cx + wOf(.55), yOf(.55), cx + wOf(1), yOf(1));
  if (sil){   // silhouette: fill the body as one mass, no interior
    noStroke(); fill(H, 24, 5, cl(88*AL,0,100));
    beginShape();
    vertex(cx-wOf(0), yOf(0)); vertex(cx-wOf(.55), yOf(.55)); vertex(cx-wOf(1), yOf(1));
    vertex(cx+wOf(1), yOf(1)); vertex(cx+wOf(.55), yOf(.55)); vertex(cx+wOf(0), yOf(0));
    endShape(CLOSE); noFill();
  } else {
    ink(58*fade, lw, near);
    for (let i=0;i<nb;i++){
      const q0 = i/nb, q1 = (i+1)/nb;
      const w0 = wOf(q0), w1 = wOf(q1), y0 = yOf(q0), y1 = yOf(q1);
      line(cx-w0, y0, cx+w1, y1); line(cx+w0, y0, cx-w1, y1);
      if (i>0) line(cx-w0, y0, cx+w0, y0);
    }
  }

  // two crossarms + the peak mast
  const arms = [[.66, .30], [.86, .215]];
  for (let a=0; a<arms.length; a++){
    const q = arms[a][0], reach = ht*arms[a][1]*jit*(.8 + .35*cl(P.scale,.3,2.0)/1.4);
    const ay = yOf(q), w0 = wOf(q);
    for (let s2=-1; s2<=1; s2+=2){
      const tx = cx + s2*(w0 + reach), ty = ay;
      ink(84*fade, lw*1.1, near); noFill();
      line(cx + s2*w0, ay, tx, ty);
      line(cx + s2*w0*.7, ay - ht*.055, tx, ty);
      line(cx + s2*w0, ay + ht*.012, tx, ty);
      if (!sil && near > .5){
        ink(52*fade, lw*.8, near);
        for (let i=1;i<3;i++){ const q2=i/3;
          line(cx + s2*(w0 + reach*q2), ay, cx + s2*(w0*.7 + reach*q2*1.02), ay - ht*.055*(1-q2)); }
      }
      // insulator string, swinging on the wind
      const sw2 = wind(ai*1.7 + a*2.3 + s2)*0.55;
      const il = ht*.075, nd = near > .55 ? 3 : 1;
      ink(76*fade, lw*.9, near); noFill();
      line(tx, ty, tx + sw2, ty + il);
      if (!sil && near > .4){ noStroke();
        for (let i=0;i<nd;i++){ const q2=(i+.6)/nd;
          if (th) fill(cl(H+40,0,360), 60, cl(60 + 30*near,8,96), cl(74*fade*AL,0,100));
          else fill(bp?196:(paper?28:H), bp?24:(paper?18:10), bp?100:(paper?60:cl(40 + 34*near,6,92)), cl(78*fade*AL,0,100));
          ellipse(tx + sw2*q2, ty + il*q2, ht*.020, ht*.010); }
        noFill();
      }
      tips.push([tx + sw2, ty + il, ai*3.1 + a*1.9 + s2*.7]);
    }
  }
  // peak mast + earth wire attachment + slow aviation lamp
  ink(84*fade, lw*1.1, near); noFill();
  line(cx, yOf(1), cx, yOf(1.06));
  line(cx - wOf(1), yOf(1), cx, yOf(1.06)); line(cx + wOf(1), yOf(1), cx, yOf(1.06));
  tips.push([cx, yOf(1.06), ai*3.1 + 9.4]);
  if (!bp && !paper && near > .35 && fr(ai*5.1 + 4.7) > .16){
    const lamp = .18 + .82*Math.pow(.5 + .5*Math.sin(K.t*.55 + ai*2.1), 3);   // slow, never a strobe
    push(); blendMode(ADD); noStroke();
    for (let i=3;i>=1;i--){ fill(th?20:8, 70, 100, cl((1.6 + 3.6*glow*lamp)*AL, 0, 16));
      ellipse(cx, yOf(1.07), ht*.035*i, ht*.035*i); }
    pop(); blendMode(BLEND);
  }
  return { tips: tips, near: near, fade: fade, lw: lw };
}

// ---- towers, far -> near, stringing the conductors back up the line --------
let prev = null;
for (let j = NP; j >= -2; j--){
  const ai = pbase + j, dj = ai - S.d + 1;
  const py = pylon(ai, dj);
  if (py && prev){
    const nn = Math.min(py.near, prev.near), fd = cl(.18 + .95*nn, 0, 1);
    const m = Math.min(py.tips.length, prev.tips.length);
    for (let c=0; c<m; c++){
      const a2 = prev.tips[c], b2 = py.tips[c];
      const span = Math.hypot(b2[0]-a2[0], b2[1]-a2[1]);
      const sag = span*(.085 + .05*(1-nn));
      ink(cl((sil?86:70)*fd, 0, 100), Math.max(.7, py.lw*(th?1.2:.75)), nn);
      noFill(); beginShape();
      for (let i=0;i<=14;i++){ const s2=i/14, bell = Math.sin(s2*Math.PI);
        const wx = wind(a2[2] + s2*2.4)*bell*(.35 + .8*nn);
        vertex(a2[0] + (b2[0]-a2[0])*s2 + wx*.35,
               a2[1] + (b2[1]-a2[1])*s2 + sag*4*s2*(1-s2) + wx);
      }
      endShape();
    }
  }
  if (py) prev = py;
}
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
